Below is a `pytest`‐style test module that exercises `deep_get` on happy paths, edge cases, and error cases.

Save this as, for example, `test_deep_get.py` alongside your implementation.

```python
import pytest
from your_module import deep_get


# Happy path: single-level key
def test_deep_get_single_key_found():
    d = {"a": 1, "b": 2}
    assert deep_get(d, "a") == 1
    assert deep_get(d, "b") == 2


# Happy path: multi-level nested keys
def test_deep_get_nested_keys_found():
    d = {
        "a": {
            "b": {
                "c": 42
            }
        }
    }
    assert deep_get(d, "a.b.c") == 42


# Edge case: intermediate key exists but is not a dict => default returned
def test_deep_get_intermediate_not_dict():
    d = {"a": 99}
    # a.b tries to index into 99, which is not a dict
    assert deep_get(d, "a.b", default="missing") == "missing"


# Edge case: missing key at the end => default (None) returned if not provided
def test_deep_get_missing_key_default_none():
    d = {"x": {"y": 5}}
    assert deep_get(d, "x.y.z") is None


# Edge case: missing key at the end => custom default returned
def test_deep_get_missing_key_custom_default():
    d = {"x": {"y": 5}}
    sentinel = object()
    assert deep_get(d, "x.y.z", default=sentinel) is sentinel


# Edge case: empty key string
def test_deep_get_empty_key_string_with_no_empty():
    d = {"": "blank", "a": 1}
    # d.get("", default) returns "blank"
    assert deep_get(d, "") == "blank"


def test_deep_get_empty_key_string_not_present():
    d = {"a": 1}
    assert deep_get(d, "", default="nope") == "nope"


# Edge case: top‐level not a dict => default returned immediately
def test_deep_get_non_dict_top_level():
    # 123 is not a dict; for first key, it returns default
    assert deep_get(123, "any.key", default="foo") == "foo"


# Error case: keys is not a string => AttributeError on split()
@pytest.mark.parametrize("bad_keys", [None, 123, 5.6, []])
def test_deep_get_non_string_keys_raises(bad_keys):
    with pytest.raises(AttributeError):
        deep_get({"a": 1}, bad_keys)


# Error case: ensure we don't swallow unexpected exceptions from dict.get
class BadDict(dict):
    def get(self, key, default=None):
        raise RuntimeError("boom")


def test_deep_get_propagates_runtime_error_from_get():
    bad = BadDict(a={"b": 2})
    with pytest.raises(RuntimeError):
        deep_get(bad, "a.b")


# Additional sanity check: default can be any type
def test_deep_get_default_can_be_any_type():
    d = {}
    class Dummy: pass
    default_dummy = Dummy()
    assert deep_get(d, "foo.bar", default=default_dummy) is default_dummy
```

Explanation of test coverage:

  * Happy paths:
    - Retrieving a top‐level key.
    - Retrieving a deeply nested key.
  * Edge cases:
    - When an intermediate lookup yields a non‐dict, we immediately return `default`.
    - Missing keys at the end return either `None` (implicit default) or a custom default.
    - An empty key string (`""`) is treated as a valid key.
    - When the top‐level object is not a dict, we don’t crash but return `default`.
  * Error cases:
    - Passing a non‐string `keys` raises an `AttributeError` on `.split()`.
    - We verify that unexpected exceptions raised by a custom dict implementation are not swallowed by `deep_get`.
